package com.ruoyi.hexu;

import java.util.*;
import java.sql.Timestamp;
import static com.ruoyi.hexu.HexuStore.*;
import static com.ruoyi.hexu.BusinessException.require;

/** Separate, bounded marketing relationships. Every reward belongs to a completed goods order. */
public final class HexuLinkCampaign {
 private final HexuStore db;
 public HexuLinkCampaign(HexuStore db){this.db=db;}
 private Set<String> skus(Map<String,Object>b){Set<String>s=new LinkedHashSet<>();Object raw=b.get("skuIds");if(raw instanceof Collection)for(Object v:(Collection<?>)raw)s.add(String.valueOf(v));else for(String v:str(b,"skuIds").split(","))if(!v.trim().isEmpty())s.add(v.trim());return s;}
 public void validate(Actor actor,long shop,Map<String,Object>b){
  validate(actor,shop,b,null);
 }
 public void validate(Actor actor,long shop,Map<String,Object>b,Map<String,Object>old){
  db.manage(actor,shop,"OWNER");
  String confirmation=str(b,"confirmationFile");
  if(!confirmation.isEmpty()){
   require(b.get("confirmationFile") instanceof String,"书面确认图片格式错误");
   HexuAttachmentAssociation.verify(db,actor,shop,confirmation,HexuAttachmentAssociation.retained(db,old,shop,"link_campaign","confirmationFile"));
  }
  if(!bool(b,"enabled"))return;
  require(!str(b,"name").trim().isEmpty()&&bool(b,"writtenConfirmed"),"启用前请填写活动名称并确认书面运营规则");
  require(number(b,"directCount")==2&&number(b,"entryFee")==0,"有效直推人数必须为2且不得收取入门费");
  require(Arrays.asList("KEEP_RELATION","EXIT_KEEP_TEAM","EXIT_PASS_ONE").contains(str(b,"relationshipMode")),"请选择明确的营销关系处置方式");
  require(!"EXIT_PASS_ONE".equals(str(b,"relationshipMode"))||Arrays.asList("EARLIEST","LATEST").contains(str(b,"passedChild")),"请确认留下的有效直推选择规则");
  require(number(b,"startsAt")>=0&&number(b,"expiresAt")>number(b,"startsAt")&&number(b,"minOrderAmount")>=100,"请确认有效期及至少1元的真实商品订单条件");
  require(number(b,"rewardCap")>0&&number(b,"maxRewardPerOrder")>0&&number(b,"totalRewardBps")>0&&number(b,"totalRewardBps")<=10000,"必须配置个人累计上限及包含原三级收益的单笔总奖励上限");
  boolean reward=false;for(String name:Arrays.asList("direct","order","peer")){long fixed=number(b,name+"Reward"),bps=number(b,name+"Bps");require(fixed>=0&&fixed<=9000000000000L&&bps>=0&&bps<=10000&&(fixed==0||bps==0),"每项奖励只能选择固定金额或比例");reward|=fixed>0||bps>0;}require(reward,"至少启用一个真实订单奖励项目");
  require(!skus(b).isEmpty(),"请明确选择参与商品");for(String sku:skus(b))db.one("select id from hx_sku where id=? and shop_id=?",sku,shop);
  require(!confirmation.isEmpty(),"请上传书面确认图片");
 }
 private Map<String,Object> current(long shop){Map<String,Object>d=db.optional("select * from hx_document where shop_id=? and kind='link_campaign' and status='ACTIVE' order by updated_at desc,id desc limit 1",shop);if(d==null)return Collections.emptyMap();Map<String,Object>b=db.parse(d.get("body_json"));long now=System.currentTimeMillis();if(!bool(b,"enabled")||number(b,"startsAt")>now||number(b,"expiresAt")<=now)return Collections.emptyMap();b.put("campaignId",str(b,"campaignId").isEmpty()?d.get("id"):b.get("campaignId"));b.put("versionId",d.get("id"));return b;}
 private void lock(String campaign){db.one("select id from hx_document where id=? for update",campaign);}
 private Map<String,Object> participant(String campaign,long agent){return db.optional("select * from hx_link_participant where campaign_id=? and agent_id=?",campaign,agent);}
 public Object join(Actor actor,long shop){db.member(actor);db.shop(shop);Map<String,Object>b=current(shop);require(!b.isEmpty(),"联动活动尚未开启或已结束");Map<String,Object>a=db.agent(actor.id,shop);require(a!=null,"仅审核通过的本店代理可以参与");String campaign=str(b,"campaignId");lock(campaign);Map<String,Object>p=participant(campaign,number(a,"id"));if(p!=null)return p;db.jdbc().update("insert into hx_link_participant(campaign_id,agent_id,shop_id,member_id,origin_parent_id,marketing_parent_id,role,status) values(?,?,?,?,?,?,'AGENT','ACTIVE')",campaign,a.get("id"),shop,actor.id,a.get("parent_id"),a.get("parent_id"));db.audit(actor,shop,"LINK_JOIN",campaign,null,map("agentId",a.get("id"),"parentId",a.get("parent_id")));return participant(campaign,number(a,"id"));}
 private boolean qualified(String campaign,long agent){return db.jdbc().queryForObject("select count(*) from hx_link_order where campaign_id=? and agent_id=? and qualifying_amount>=threshold_amount",Long.class,campaign,agent)>0;}
 private long direct(String campaign,long agent){return db.jdbc().queryForObject("select count(*) from hx_link_participant p join hx_agent a on a.id=p.agent_id where p.campaign_id=? and p.origin_parent_id=? and p.status='ACTIVE' and a.status='ACTIVE' and a.shop_id=p.shop_id and exists(select 1 from hx_link_order o where o.campaign_id=p.campaign_id and o.agent_id=p.agent_id and o.is_new_agent=true and o.qualifying_amount>=o.threshold_amount)",Long.class,campaign,agent);}
 private boolean recipient(String campaign,long agent,long shop){Map<String,Object>p=participant(campaign,agent);return p!=null&&"ACTIVE".equals(str(p,"status"))&&qualified(campaign,agent)&&db.optional("select id from hx_agent where id=? and shop_id=? and status='ACTIVE'",agent,shop)!=null;}
 public Map<String,Object> capture(long buyer,long shop,long ownerAgent){
  Map<String,Object>b=current(shop);if(b.isEmpty())return b;Map<String,Object>a=db.agent(buyer,shop);if(a==null)return Collections.emptyMap();Map<String,Object>p=participant(str(b,"campaignId"),number(a,"id"));if(p==null||!"ACTIVE".equals(str(p,"status")))return Collections.emptyMap();
  Map<String,Object>snapshot=new LinkedHashMap<>(b);snapshot.remove("confirmationFile");snapshot.remove("uploads");snapshot.put("agentId",a.get("id"));snapshot.put("ownerAgentId",ownerAgent);snapshot.put("originParentId",p.get("origin_parent_id"));snapshot.put("parentId",p.get("marketing_parent_id"));snapshot.put("buyerRole",p.get("role"));Map<String,Object>parent=participant(str(b,"campaignId"),number(p,"marketing_parent_id"));long peer=parent==null?0:number(parent,"marketing_parent_id");snapshot.put("peerId",peer);Map<String,Object>other=participant(str(b,"campaignId"),peer);snapshot.put("peerRole",other==null?"":str(other,"role"));snapshot.put("isNewAgent",a.get("approved_at") instanceof Timestamp&&((Timestamp)a.get("approved_at")).getTime()>=number(b,"startsAt"));return snapshot;
 }
 @SuppressWarnings("unchecked") private Map<String,Object> plan(List<Map<String,Object>>lines){if(lines.isEmpty())return Collections.emptyMap();Object raw=db.parse(lines.get(0).get("snapshot_json")).get("linkCampaign");return raw instanceof Map?(Map<String,Object>)raw:Collections.emptyMap();}
 private long qualifying(List<Map<String,Object>>lines,Map<String,Object>b){long total=0;Set<String>ids=skus(b);for(Map<String,Object>l:lines)if(ids.contains(str(l,"sku_id")))total=Math.addExact(total,number(l,"paid")-number(l,"refunded_paid"));return total;}
 private long requested(Map<String,Object>b,String name,long base){return number(b,name+"Reward")>0?number(b,name+"Reward"):SettlementCalculator.proportion(base,number(b,name+"Bps"),10000);}
 public void completed(Map<String,Object>o){
  String order=str(o,"id");List<Map<String,Object>>lines=db.jdbc().queryForList("select * from hx_order_line where order_id=? order by id",order);Map<String,Object>b=plan(lines);if(b.isEmpty()||number(b,"expiresAt")<System.currentTimeMillis())return;String campaign=str(b,"campaignId");lock(campaign);long agent=number(b,"agentId"),shop=number(o,"shop_id"),eligible=qualifying(lines,b);if(!recipientExists(campaign,agent,shop)||eligible<number(b,"minOrderAmount")||db.optional("select order_id from hx_link_order where order_id=?",order)!=null)return;
  db.jdbc().update("insert into hx_link_order(order_id,campaign_id,shop_id,agent_id,qualifying_amount,threshold_amount,is_new_agent) values(?,?,?,?,?,?,?)",order,campaign,shop,agent,eligible,number(b,"minOrderAmount"),bool(b,"isNewAgent"));
  // Fixed order: direct, own order, second-level peer; at most three recipients.
  long parent=number(b,"parentId"),peer=number(b,"peerId");boolean first=bool(b,"isNewAgent")&&db.jdbc().queryForObject("select count(*) from hx_link_order where campaign_id=? and agent_id=?",Long.class,campaign,agent)==1&&db.jdbc().queryForObject("select count(*) from hx_link_reward where campaign_id=? and subject_agent_id=? and reward_type='LINK_DIRECT'",Long.class,campaign,agent)==0;
  if(first&&parent>0&&parent!=agent&&recipient(campaign,parent,shop))award(o,b,lines,parent,"LINK_DIRECT",requested(b,"direct",eligible),eligible);
  award(o,b,lines,agent,"LINK_ORDER",requested(b,"order",eligible),eligible);
  if(peer>0&&peer!=parent&&peer!=agent&&"BOSS".equals(str(b,"buyerRole"))&&"BOSS".equals(str(b,"peerRole"))&&recipient(campaign,peer,shop))award(o,b,lines,peer,"LINK_PEER",requested(b,"peer",eligible),eligible);
  recalculate(campaign,agent,b,order);long origin=number(b,"originParentId");if(origin>0)recalculate(campaign,origin,b,order);
 }
 private boolean recipientExists(String campaign,long agent,long shop){Map<String,Object>p=participant(campaign,agent);return p!=null&&"ACTIVE".equals(str(p,"status"))&&db.optional("select id from hx_agent where id=? and shop_id=? and status='ACTIVE'",agent,shop)!=null;}
 private void award(Map<String,Object>o,Map<String,Object>b,List<Map<String,Object>>lines,long agent,String type,long requested,long eligible){
  if(requested<=0)return;String order=str(o,"id"),campaign=str(b,"campaignId");long shop=number(o,"shop_id"),owner=number(b,"ownerAgentId"),subject=number(b,"agentId");
  long used=db.jdbc().queryForObject("select coalesce(sum(amount),0) from hx_link_reward where campaign_id=? and recipient_agent_id=?",Long.class,campaign,agent);
  long existing=db.jdbc().queryForObject("select coalesce(sum(case when amount-reversed>0 then amount-reversed else 0 end),0) from hx_earning where order_id=?",Long.class,order);
  long totalCap=Math.min(number(b,"maxRewardPerOrder"),SettlementCalculator.proportion(eligible,number(b,"totalRewardBps"),10000));
  Set<String>skuIds=skus(b);List<Map<String,Object>>margins=new ArrayList<>();long margin=0;for(Map<String,Object>l:lines)if(skuIds.contains(str(l,"sku_id"))){long available=db.jdbc().queryForObject("select coalesce(sum(amount-reversed),0) from hx_earning where order_id=? and line_id=? and agent_id=?",Long.class,order,l.get("id"),owner);require(available>=0,"商城剩余毛利异常");margins.add(map("lineId",l.get("id"),"margin",available));margin=Math.addExact(margin,available);}
  long amount=Math.max(0,Math.min(Math.min(requested,number(b,"rewardCap")-used),Math.min(margin,totalCap-existing)));
  db.jdbc().update("insert into hx_link_reward(order_id,campaign_id,shop_id,subject_agent_id,recipient_agent_id,reward_type,amount,snapshot_json) values(?,?,?,?,?,?,?,?)",order,campaign,shop,subject,agent,type,amount,db.json(b));
  long cumulative=0,prior=0;for(Map<String,Object>l:margins){cumulative+=number(l,"margin");long next=margin==0?0:SettlementCalculator.proportion(amount,cumulative,margin),part=next-prior;prior=next;if(part==0)continue;db.jdbc().update("insert into hx_earning(order_id,line_id,shop_id,agent_id,earning_type,amount) values(?,?,?,?,?,?)",order,l.get("lineId"),shop,agent,type,part);db.jdbc().update("insert into hx_earning(order_id,line_id,shop_id,agent_id,earning_type,amount) values(?,?,?,?,? ,?)",order,l.get("lineId"),shop,owner,"LINK_COST",-part);}
  db.audit(new Actor(0,true,true),shop,"LINK_REWARD",order,null,map("type",type,"recipient",agent,"requested",requested,"amount",amount,"campaignId",campaign));
 }
 private void recalculate(String campaign,long agent,Map<String,Object>b,String order){Map<String,Object>p=participant(campaign,agent);if(p==null)return;boolean boss=qualified(campaign,agent)&&direct(campaign,agent)>=2;String role=boss?"BOSS":"AGENT";if(role.equals(str(p,"role")))return;db.jdbc().update("update hx_link_participant set role=? where campaign_id=? and agent_id=?",role,campaign,agent);db.audit(new Actor(0,true,true),number(p,"shop_id"),"LINK_ROLE",order,p,map("role",role,"validDirect",direct(campaign,agent)));
  if(!boss||bool(p,"promoted_once"))return;db.jdbc().update("update hx_link_participant set promoted_once=true where campaign_id=? and agent_id=?",campaign,agent);String mode=str(b,"relationshipMode");if("KEEP_RELATION".equals(mode)||number(p,"marketing_parent_id")==0)return;
  Map<String,Object>parent=participant(campaign,number(p,"marketing_parent_id"));long target=parent==null?0:number(parent,"marketing_parent_id");Long child=null;if("EXIT_PASS_ONE".equals(mode)){List<Map<String,Object>>children=db.jdbc().queryForList("select p.agent_id from hx_link_participant p where p.campaign_id=? and p.origin_parent_id=? and p.marketing_parent_id=? and exists(select 1 from hx_link_order o where o.campaign_id=p.campaign_id and o.agent_id=p.agent_id and o.is_new_agent=true and o.qualifying_amount>=o.threshold_amount) order by p.joined_at "+("LATEST".equals(str(b,"passedChild"))?"desc":"asc")+",p.agent_id",campaign,agent,agent);if(!children.isEmpty())child=number(children.get(0),"agent_id");}
  Map<String,Object>body=map("name","营销老板关系处置","campaignId",campaign,"agentId",agent,"fromParentId",p.get("marketing_parent_id"),"targetParentId",target,"passedAgentId",child,"relationshipMode",mode,"triggerOrder",order,"ruleVersion",b.get("versionId"));String doc=id("LINKREL");db.jdbc().update("insert into hx_document(id,shop_id,member_id,kind,status,body_json) values(?,?,?,'link_relation','PENDING',?)",doc,p.get("shop_id"),p.get("member_id"),db.json(body));db.audit(new Actor(0,true,true),number(p,"shop_id"),"LINK_RELATION_PROPOSE",doc,null,body);
 }
 public void reviewRelation(Actor actor,long shop,Map<String,Object>b){db.manage(actor,shop,"OWNER");String campaign=str(b,"campaignId");lock(campaign);long agent=number(b,"agentId"),target=number(b,"targetParentId");Map<String,Object>p=participant(campaign,agent);require(p!=null&&"BOSS".equals(str(p,"role"))&&qualified(campaign,agent)&&direct(campaign,agent)>=2,"营销身份条件已变化，请重新评估");require(number(p,"marketing_parent_id")==number(b,"fromParentId"),"营销关系已变化，请重新提交");Set<Long>seen=new HashSet<>();seen.add(agent);for(long next=target;next>0;){require(seen.add(next),"营销关系不能形成循环");Map<String,Object>parent=participant(campaign,next);require(parent!=null&&number(parent,"shop_id")==shop,"目标营销关系不在本商城");next=number(parent,"marketing_parent_id");}
  long child=number(b,"passedAgentId");if(child>0){Map<String,Object>c=participant(campaign,child);require(c!=null&&number(c,"marketing_parent_id")==agent&&qualified(campaign,child),"拟留人关系或资格已变化");db.jdbc().update("update hx_link_participant set marketing_parent_id=? where campaign_id=? and agent_id=?",number(b,"fromParentId"),campaign,child);}
  db.jdbc().update("update hx_link_participant set marketing_parent_id=? where campaign_id=? and agent_id=?",target==0?null:target,campaign,agent);db.audit(actor,shop,"LINK_RELATION_APPLY",str(b,"triggerOrder"),p,b);
 }
 public void reversed(String order){Map<String,Object>record=db.optional("select * from hx_link_order where order_id=?",order);if(record==null)return;List<Map<String,Object>>lines=db.jdbc().queryForList("select * from hx_order_line where order_id=? order by id",order);Map<String,Object>b=plan(lines);String campaign=str(record,"campaign_id");lock(campaign);db.jdbc().update("update hx_link_order set qualifying_amount=? where order_id=?",qualifying(lines,b),order);recalculate(campaign,number(record,"agent_id"),b,order);long origin=number(b,"originParentId");if(origin>0)recalculate(campaign,origin,b,order);}
 public Map<String,Object> status(Actor actor,long shop){db.member(actor);Map<String,Object>b=current(shop);boolean enabled=!b.isEmpty();Map<String,Object>a=db.agent(actor.id,shop);if(b.isEmpty()&&a!=null){Map<String,Object>last=db.optional("select d.* from hx_link_participant p join hx_document d on d.id=p.campaign_id where p.shop_id=? and p.agent_id=? order by p.joined_at desc limit 1",shop,a.get("id"));if(last!=null){b=db.parse(last.get("body_json"));b.put("campaignId",last.get("id"));}}Map<String,Object>p=a==null||b.isEmpty()?null:participant(str(b,"campaignId"),number(a,"id"));Map<String,Object>publicPlan=new LinkedHashMap<>();for(String key:Arrays.asList("name","campaignId","directCount","minOrderAmount","rewardCap","maxRewardPerOrder","totalRewardBps","skuIds","startsAt","expiresAt","relationshipMode","passedChild","directReward","orderReward","peerReward","directBps","orderBps","peerBps"))if(b.containsKey(key))publicPlan.put(key,b.get(key));long earned=0,gross=0;List<Map<String,Object>>records=Collections.emptyList(),children=Collections.emptyList();if(p!=null){String campaign=str(b,"campaignId");long id=number(p,"agent_id");gross=db.jdbc().queryForObject("select coalesce(sum(amount),0) from hx_link_reward where campaign_id=? and recipient_agent_id=?",Long.class,campaign,id);records=db.jdbc().queryForList("select e.order_id,e.earning_type,e.amount,e.reversed,e.status from hx_earning e join hx_link_order o on o.order_id=e.order_id where o.campaign_id=? and e.agent_id=? and e.earning_type in ('LINK_DIRECT','LINK_ORDER','LINK_PEER') order by e.id desc limit 200",campaign,id);earned=db.jdbc().queryForObject("select coalesce(sum(e.amount-e.reversed),0) from hx_earning e join hx_link_order o on o.order_id=e.order_id where o.campaign_id=? and e.agent_id=? and e.earning_type in ('LINK_DIRECT','LINK_ORDER','LINK_PEER')",Long.class,campaign,id);children=db.jdbc().queryForList("select p.agent_id,p.member_id,p.role from hx_link_participant p where p.campaign_id=? and p.origin_parent_id=?",campaign,id);for(Map<String,Object>c:children)c.put("qualified",qualified(campaign,number(c,"agent_id")));}return map("enabled",enabled,"campaign",publicPlan,"canJoin",a!=null,"participant",p,"qualified",p!=null&&qualified(str(b,"campaignId"),number(p,"agent_id")),"validDirect",p==null?0:direct(str(b,"campaignId"),number(p,"agent_id")),"earned",earned,"gross",gross,"records",records,"children",children);}
}
